"""Grandfather-father-son snapshot retention. See task.md."""

from __future__ import annotations

import re
from datetime import datetime
from typing import Callable, Hashable, NamedTuple


class RetentionError(ValueError):
    """Raised for an unusable policy or an unusable list of snapshots."""


class Kept(NamedTuple):
    snapshot: str
    reasons: tuple[str, ...]


RULES = ("last", "hourly", "daily", "weekly", "monthly", "yearly")

_TIMESTAMP_FORM = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}")

_BUCKETS: dict[str, Callable[[datetime], Hashable]] = {
    "hourly": lambda t: (t.date(), t.hour),
    "daily": lambda t: t.date(),
    "weekly": lambda t: t.isocalendar()[:2],
    "monthly": lambda t: (t.year, t.month),
    "yearly": lambda t: t.year,
}


def _parse(snapshot: object) -> datetime:
    if not isinstance(snapshot, str) or not _TIMESTAMP_FORM.fullmatch(snapshot):
        raise RetentionError(f"not a snapshot timestamp: {snapshot!r}")
    try:
        return datetime.strptime(snapshot, "%Y-%m-%dT%H:%M:%S")
    except ValueError as exc:
        raise RetentionError(f"not a real date and time: {snapshot!r}") from exc


def _validate_policy(policy: object) -> None:
    if not isinstance(policy, dict):
        raise RetentionError("policy must be a dict")
    for rule, count in policy.items():
        if rule not in RULES:
            raise RetentionError(f"unknown rule: {rule!r}")
        if isinstance(count, bool) or not isinstance(count, int):
            raise RetentionError(f"count for {rule!r} must be an int: {count!r}")
        if count < 0:
            raise RetentionError(f"count for {rule!r} is negative: {count!r}")
    if not any(policy.values()):
        raise RetentionError("policy keeps nothing")


def retain(snapshots: list[str], policy: dict) -> list[Kept]:
    """Return the snapshots `policy` keeps, newest first, with the rules that keep each."""
    _validate_policy(policy)
    parsed = [(_parse(snapshot), snapshot) for snapshot in snapshots]
    if len({name for _, name in parsed}) != len(parsed):
        raise RetentionError("duplicate snapshot timestamp")
    parsed.sort(key=lambda pair: pair[0], reverse=True)

    reasons: dict[str, list[str]] = {name: [] for _, name in parsed}
    for rule in RULES:
        count = policy.get(rule, 0)
        if not count:
            continue
        if rule == "last":
            kept = [name for _, name in parsed[:count]]
        else:
            bucket = _BUCKETS[rule]
            seen: set[Hashable] = set()
            kept = []
            for when, name in parsed:
                key = bucket(when)
                if key in seen:
                    continue
                seen.add(key)
                kept.append(name)
                if len(kept) == count:
                    break
        for name in kept:
            reasons[name].append(rule)

    return [Kept(name, tuple(reasons[name])) for _, name in parsed if reasons[name]]
